 82	                        if (snake.isAlive()) {
 83	                            snake.setDead();
 84	                            setFoodLevel(TUNING.foodValueFor(Snake.class));
 85	                            return where;
 86	                        }
 87	                    } else if (animal instanceof Plant) {
 88	                        Plant plant = (Plant) animal;
 89	                        if (plant.isAlive()) {
 90	                            plant.setDead();
 91	                            return where;
 92	                        }
 93	                    }
 94	                }
 95	            }
 96	            return null;
 97	        }
 98	        else {
 99	            Field field = getField();
100	            List<Location> adjacent = field.adjacentLocations(getLocation());
101	            Iterator<Location> it = adjacent.iterator();
102	            while (it.hasNext()) {
103	                Location where = it.next();
104	                Object animal = field.getObjectAt(where);
105	                if (animal instanceof Snake) {
106	                    Snake snake = (Snake) animal;
107	                    if (snake.isAlive()) {
108	                        snake.setDead();
109	                        setFoodLevel(TUNING.foodValueFor(Snake.class));
110	                        return where;
111	                    }
112	                }
113	                else if (animal instanceof Plant){
114	                    Plant plant = (Plant) animal;
115	                    if(plant.isAlive()) {
116	                        plant.setDead();
117	                        return where;
118	                    }
119	                }
120	            }
121	            return null;
122	        }
123	    }
