  5	/**
  6	 * A simple model of an ant.
  7	 * Ants age, move, eat acacia and grass, breed, and die.
  8	 *
  9	 * @version 01.03.22
 10	 */
 11	public class Ant extends Animal
 12	{
 13	    private static final SpeciesTuning.AnimalTuning TUNING = SpeciesTuning.ant();
 14	    // A shared random number generator to control breeding.
 15	    private static final Random rand = Randomizer.getRandom();
 16	
 17	    /**
 18	     * Create an ant. An ant can be created as a newborn (age zero
 19	     * and not hungry) or with a random age and food level.
 20	     *
 21	     * @param randomAge If true, the ant will have random age and hunger level.
 22	     * @param field The field currently occupied.
 23	     * @param location The location within the field.
 24	     */
 25	    public Ant(boolean randomAge, Field field, Location location) {
 26	        super(field, location);
 27	        this.setGender();
 28	        if(randomAge) {
 29	            setAge(rand.nextInt(TUNING.getMaxAge()));
 30	            setFoodLevel(rand.nextInt(TUNING.getNewbornFoodLevel()));
 31	        }
 32	        else {
 33	            setAge(0);
 34	            setFoodLevel(TUNING.getNewbornFoodLevel());
 35	        }
 36	    }
 37	
 38	    /**
 39	     * This is what the ant does most of the time: it eats grass
 40	     * and acacia. In the process, it might breed, die of hunger,
 41	     * or die of old age.
 42	     * @param newAnts A list to return newly born ants.
 43	     * @param time the current time in the simulation
 44	     */
 45	    public void act(List<Animal> newAnts, int time) {
 46	        incrementAge(TUNING.getMaxAge());
 47	        incrementHunger();
 48	
 49	        if(isAlive() && TUNING.isActive(time))
 50	        {
 51	            if (getDisease()) {
 52	                spreadDisease();
 53	            }
 54	            if (giveBirth(TUNING.getBreedingAge())) {
 55	                breedOffspring(newAnts, TUNING.getBreedingAge(),
 56	                        TUNING.getBreedingProbability(), TUNING.getMaxLitterSize());
 57	            }
 58	
 59	            Location newLocation = findFood();
 60	            if(newLocation == null) {
 61	                newLocation = getField().freeAdjacentLocation(getLocation());
 62	            }
 63	            moveOrDie(newLocation);
 64	        }
 65	    }
 66	
 67	    /**
 68	     * Look for acacia and grass adjacent to the current location.
 69	     * Only the first grass or acacia is eaten.
 70	     * @return Where food was found, or null if it wasn't.
 71	     */
 72	    private Location findFood() {
 73	        Field field = getField();
 74	        List<Location> adjacent = field.adjacentLocations(getLocation());
 75	        Iterator<Location> it = adjacent.iterator();
 76	        while(it.hasNext()) {
 77	            Location where = it.next();
 78	            Object plant = field.getObjectAt(where);
 79	            if(plant instanceof Acacia) {
 80	                Acacia acacia = (Acacia) plant;
 81	                if (acacia.isAlive()) {
 82	                    acacia.setDead();
 83	                    setFoodLevel(TUNING.foodValueFor(Acacia.class));
 84	                    return where;
 85	                }
 86	            }
 87	            else if (plant instanceof Grass) {
 88	                Grass grass = (Grass) plant;
 89	                if(grass.isAlive()) {
 90	                    grass.setDead();
 91	                    setFoodLevel(TUNING.foodValueFor(Grass.class));
 92	                    return where;
 93	                }
 94	            }
 95	        }
 96	        return null;
 97	    }
